#!/usr/bin/env python3
"""Generate the embedded catalog. --check is suitable for CI; no runtime JSON dependency."""

import argparse
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PLACEHOLDER = re.compile(r"(?<!\{)\{[^{}]*\}(?!\})")


def generate():
    source = ROOT / "player/cinder-ui/locales/zh-CN.json"
    pairs = json.loads(source.read_text(encoding="utf8"))
    quote = lambda value: json.dumps(value, ensure_ascii=False)
    output = [
        "// Generated by tools/generate_locales.py; edit locales/zh-CN.json instead.\n",
        "#[rustfmt::skip]\npub(super) fn chinese(source: &str) -> Option<&'static str> {\n"
        "    match source {\n",
    ]

    for english, chinese in sorted(pairs.items()):
        if not isinstance(chinese, str):
            raise ValueError(f"Translation must be a string: {english}")
        output.append(f"        {quote(english)} => Some({quote(chinese)}),\n")
    output.append("        _ => None,\n    }\n}\n")

    output.append(
        "\n/// Format translated templates with the same arguments, checked by Rust.\n"
        "#[macro_export]\nmacro_rules! ui_format {\n"
    )
    for english, chinese in sorted(pairs.items()):
        if english == chinese or not PLACEHOLDER.search(english):
            continue
        fields = lambda value: PLACEHOLDER.findall(value)
        if sorted(fields(english)) != sorted(fields(chinese)):
            raise ValueError(f"Placeholder mismatch: {english}")
        output.append(
            f"    ({quote(english)} $(, $($args:tt)*)?) => {{\n"
            f"        if $crate::i18n::is_chinese() {{ format!({quote(chinese)} $(, $($args)*)?) }}\n"
            f"        else {{ format!({quote(english)} $(, $($args)*)?) }}\n"
            "    };\n"
        )
    output.append(
        "    ($fmt:literal $(, $($args:tt)*)?) => { format!($fmt $(, $($args)*)?) };\n}\n"
    )
    return "".join(output)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()

    path = ROOT / "player/cinder-ui/src/i18n_catalog.rs"
    body = generate()
    if args.check:
        if not path.exists() or path.read_text(encoding="utf8") != body:
            raise SystemExit("Catalog is stale; run tools/generate_locales.py")
    else:
        path.write_text(body, encoding="utf8", newline="\n")


if __name__ == "__main__":
    main()
